mapper.select:
SELECT t.*, u.real_name AS creatorName, u2.real_name AS assigneeName, d.dept_name AS deptName
FROM ticket t
LEFT JOIN sys_user u ON t.creator_id = u.id
LEFT JOIN sys_user u2 ON t.assignee_id = u2.id
LEFT JOIN sys_dept d ON t.dept_id = d.id
WHERE t.deleted = 0

    AND t.ticket_no LIKE CONCAT('%', #{query.ticketNo}, '%')


    AND t.title LIKE CONCAT('%', #{query.title}, '%')


    AND t.status = #{query.status}


    AND t.priority = #{query.priority}


    AND t.assignee_id = #{query.assigneeId}


    AND t.dept_id = #{query.deptId}


    AND t.create_time >= #{query.startTime}


    AND t.create_time <= #{query.endTime}


    AND t.dept_id IN

        #{deptId}


ORDER BY t.create_time DESC
